// ---------- Dépôt ----------

[Fact]
public void Deposit_Empty_IsInvalid() =>
    AssertRefused(AtmStatus.InvalidAmount, A(10, 0), N(0, 0, 0), Denomination.Ten, new Operation.Deposit(NoteCounts.None));

[Fact]
public void Deposit_Jammed_CheckedBeforeFull() =>
    AssertRefused(AtmStatus.CassetteJammed, A(10, 0), N(5, 5, 5), Denomination.Fifty, new Operation.Deposit(N(1, 1, 1)));

[Fact]
public void Deposit_OtherCassetteJammed_IsAccepted()
{
    var (result, dispenser) = Run(A(0, 200), N(0, 0, 4), Denomination.Fifty, new Operation.Deposit(N(0, 1, 1)));

    Assert.Equal(new AtmResult(AtmStatus.Ok, NoteCounts.None, 0, A(30, 200)), result);
    Assert.Equal(N(0, 1, 5), dispenser.Stock);
}

[Fact]
public void Deposit_FullTens_IsRefused() =>
    AssertRefused(AtmStatus.CassetteFull, A(10, 0), N(0, 0, 5), null, new Operation.Deposit(N(1, 1, 1)));

// ---------- Pannes du module ----------

[Fact]
    Assert.Equal(N(1, 5, 1), dispenser.Stock);
}

[Fact]
public void Scenario_JammedCassette_StaysUntouchedAcrossOperations()
{
    var dispenser = new MoneyDispenser(N(5, 2, 3), Denomination.Fifty);
    var machine = new CashMachine(dispenser);

    // 100 sans les 50 : au plus 20×2 + 10×3 = 70 → refus.
    var refused = machine.Execute(A(250, 0), new Operation.Withdraw(100));
    Assert.Equal(new AtmResult(AtmStatus.CannotDispense, NoteCounts.None, 0, A(250, 0)), refused);
    Assert.Equal(N(5, 2, 3), dispenser.Stock);

    // 70 : 20×2 + 10×3, les 50 restent en place.
    var ok = machine.Execute(A(250, 0), new Operation.Withdraw(70));
    Assert.Equal(new AtmResult(AtmStatus.Ok, N(0, 2, 3), 0, A(180, 70)), ok);
    Assert.Equal(N(5, 0, 0), dispenser.Stock);

    // Dépôt contenant un 50 : refusé, même si les autres cassettes ont de la place.
    var jammed = machine.Execute(ok.Account, new Operation.Deposit(N(1, 1, 1)));
    Assert.Equal(new AtmResult(AtmStatus.CassetteJammed, NoteCounts.None, 0, A(180, 70)), jammed);
    Assert.Equal(N(5, 0, 0), dispenser.Stock);

    // Dépôt sans 50 : accepté.
    var deposit = machine.Execute(ok.Account, new Operation.Deposit(N(0, 1, 1)));
    Assert.Equal(new AtmResult(AtmStatus.Ok, NoteCounts.None, 0, A(210, 70)), deposit);
}

private static (AtmResult Result, NoteCounts Stock) ExpectedDeposit(
    AccountState account, NoteCounts notes, NoteCounts stock, Denomination? jammed)
{
    AtmResult Refusal(AtmStatus status) => new(status, NoteCounts.None, 0, account);

    if (notes.Total == 0)
    {
        return (Refusal(AtmStatus.InvalidAmount), stock);
    }

    if (jammed is { } j && notes.Of(j) > 0)
    {
        return (Refusal(AtmStatus.CassetteJammed), stock);
    }

    if (stock.Fifties + notes.Fifties > 5 || stock.Twenties + notes.Twenties > 5 || stock.Tens + notes.Tens > 5)
    {
        return (Refusal(AtmStatus.CassetteFull), stock);
    }

    var after = new AccountState(account.Balance + notes.Value, account.WithdrawnToday);

    return (new AtmResult(AtmStatus.Ok, NoteCounts.None, 0, after), stock + notes);
}
}

// ====================================================================================================
// Dépôt
// ====================================================================================================

/// <summary>Le statut est celui du premier contrôle qui échoue, dans l'ordre de la spécification ; sinon Ok.</summary>
[Property(Arbitrary = [typeof(Generateurs)], Replay = Graine, MaxTest = Cas)]
public void Depot_LeStatutEstCeluiDuPremierControleQuiEchoue(Situation situation, Depot depot)
{
    var billets = depot.Billets;
    var apres = situation.Stock + billets;
    var attendu =
        billets.Total == 0 ? AtmStatus.InvalidAmount
        : situation.Jammed is { } bloquee && billets.Of(bloquee) > 0 ? AtmStatus.CassetteJammed
        : Domaine.Coupures.Any(c => apres.Of(c) > 5) ? AtmStatus.CassetteFull
        : AtmStatus.Ok;

    var (result, _) = situation.Run(depot.Operation);

    Assert.Equal(attendu, result.Status);
    Assert.Contains(result.Status, StatutsDepot);
}

/// <summary>Sur un refus, rien ne change : pas de billets, pas de frais, compte et stock identiques.</summary>
[Property(Arbitrary = [typeof(Generateurs)], Replay = Graine, MaxTest = Cas)]
public void Depot_UnRefusNeChangeRien(Situation situation, Depot depot)
{
    var (result, stockApres) = situation.Run(depot.Operation);

    if (result.Status != AtmStatus.Ok)
    {
        AssertRefusSansEffet(situation, result, stockApres);
    }
}

/// <summary>
/// Un dépôt réussi range exactement les billets déposés, crédite leur valeur, ne touche pas au retrait du
/// jour, ne sort rien et ne prend pas de frais.
/// </summary>
[Property(Arbitrary = [typeof(Generateurs)], Replay = Graine, MaxTest = Cas)]
public void Depot_UnSuccesRangeLesBilletsEtCrediteLeurValeur(Situation situation, Depot depot)
{
    var (result, stockApres) = situation.Run(depot.Operation);

    if (result.Status == AtmStatus.Ok)
    {
        var credite = situation.Account with { Balance = situation.Account.Balance + depot.Billets.Value };
        Assert.Equal(new AtmResult(AtmStatus.Ok, NoteCounts.None, 0, credite), result);
        Assert.Equal(situation.Stock + depot.Billets, stockApres);
    }
}

/// <summary>Un dépôt ne sort jamais de billets ; un refus n'appelle pas le module ; un succès range le dépôt.</summary>
[Property(Arbitrary = [typeof(Generateurs)], Replay = Graine, MaxTest = Cas)]
public void Depot_NeFaitQueRangerDesBillets(Situation situation, Depot depot)
{
    var (result, espion) = situation.RunSpied(depot.Operation);

    Assert.Empty(espion.Dispenses);
    if (result.Status != AtmStatus.Ok)
    {
        Assert.Empty(espion.Loads);
        return;
    }

    Assert.All(espion.Loads, load => Assert.True(load.Ok, $"dépôt refusé par le module : {load.Notes}"));
    Assert.Equal(depot.Billets, Somme(espion.Loads.Select(l => l.Notes)));
}

/// <summary>
/// Une cassette bloquée que le dépôt ne touche pas ne change rien ; un dépôt non vide qui la touche est
/// toujours refusé en CassetteJammed, quel que soit le remplissage.
/// </summary>
[Property(Arbitrary = [typeof(Generateurs)], Replay = Graine, MaxTest = Cas)]
public void Depot_LaCassetteBloqueeNeCompteQueSiLeDepotLaTouche(Situation situation, Depot depot)
{
    var (result, stockApres) = situation.Run(depot.Operation);
    var (resultDebloque, stockDebloque) = situation.WithJam(null).Run(depot.Operation);

    if (situation.Jammed is { } bloquee && depot.Billets.Of(bloquee) > 0)
    {
        Assert.Equal(AtmStatus.CassetteJammed, result.Status);
    }
    else
    {
        Assert.Equal(resultDebloque, result);
        Assert.Equal(stockDebloque, stockApres);
    }
}

