input.command:
cat > Atm.Tests/Tmp.cs <<'EOF'
namespace Atm.Tests;
public class TmpCheck { [Fact] public void T() {
  var r = new CashMachine(new MoneyDispenser(new NoteCounts(5,0,0), Denomination.Fifty)).Execute(new AccountState(10,0), new Operation.Deposit(new NoteCounts(1,0,0)));
  Assert.Fail("STATUT=" + r.Status); } }
EOF
dotnet test Atm.slnx --filter "FullyQualifiedName~TmpCheck" 2>&1 | grep -o 'STATUT=[A-Za-z]*' | head -1; rm Atm.Tests/Tmp.cs
cat > PATCH.md <<'EOF'
Le bug viole l'ordre des contrôles du dépôt (contrôle n° 2 avant le n° 3) : un dépôt qui contient un billet de la cassette bloquée doit être refusé en `CassetteJammed`, mais si cette cassette bloquée est pleine (5 billets), la machine répond `CassetteFull` (ex. : stock 50×5, 50 bloquée, dépôt 50×1).
EOF
sh ci/controle.sh

